#include "al_brush.h"
#include <sstream>
#include <iomanip>
#include <locale>
namespace al { namespace brushio {
struct Lexer {const std::string& s;size_t at=0;std::string pending;explicit Lexer(const std::string& s):s(s){}std::string next(){if(!pending.empty()){auto p=pending;pending.clear();return p;}while(at<s.size()){if((unsigned char)s[at]<=32){at++;continue;}if(s.compare(at,2,"//")==0){auto p=s.find('\n',at);at=p==s.npos?s.size():p+1;continue;}break;}if(at>=s.size())return {};char c=s[at++];if(c=='"'){std::string out;bool closed=false;while(at<s.size()){c=s[at++];if(c=='"'){closed=true;break;}if(c=='\\'&&at<s.size())c=s[at++];out+=c;}if(!closed)throw std::runtime_error("unclosed MAP string");return '\"'+out+'\"';}if(std::string("{}()[]").find(c)!=std::string::npos)return std::string(1,c);std::string out(1,c);while(at<s.size()&&(unsigned char)s[at]>32&&std::string("{}()[]").find(s[at])==std::string::npos)out+=s[at++];return out;}void put(const std::string& p){pending=p;}void expect(const char* p){if(next()!=p)throw std::runtime_error(std::string("expected MAP token ")+p);}double num(){auto t=next();size_t end=0;double n;try{n=std::stod(t,&end);}catch(...){throw std::runtime_error("invalid MAP number");}if(end!=t.size()||!std::isfinite(n))throw std::runtime_error("invalid MAP number");return n;}};
inline std::string unquote(std::string s){if(s.size()>=2&&s.front()=='"'&&s.back()=='"')return s.substr(1,s.size()-2);return s;}
inline Vec3 point(Lexer& l){l.expect("(");Vec3 p{l.num(),l.num(),l.num()};l.expect(")");return p;}
inline void standardAxes(Face& f){auto n=f.normal();if(std::abs(n.z)>=std::abs(n.x)&&std::abs(n.z)>=std::abs(n.y)){f.u={1,0,0};f.v={0,-1,0};}else if(std::abs(n.x)>=std::abs(n.y)){f.u={0,1,0};f.v={0,0,-1};}else{f.u={1,0,0};f.v={0,0,-1};}double c=std::cos(f.rotation*3.141592653589793/180),s=std::sin(f.rotation*3.141592653589793/180);auto u=f.u,v=f.v;f.u=u*c-v*s;f.v=u*s+v*c;}
inline double snap(double n){n=std::round(n*1024)/1024;return n==0?0:n;}
inline void point(std::ostream& o,Vec3 p){o<<"( "<<snap(p.x)<<' '<<snap(p.y)<<' '<<snap(p.z)<<" ) ";}
inline Vec3 entityVector(std::string text){auto first=text.find_first_not_of(" \t\r\n"),last=text.find_last_not_of(" \t\r\n");if(first==std::string::npos)throw std::runtime_error("invalid entity vector");text=text.substr(first,last-first+1);if(text.size()>=2&&text.front()=='\''&&text.back()=='\'')text=text.substr(1,text.size()-2);std::istringstream in(text);in.imbue(std::locale::classic());Vec3 p;if(!(in>>p.x>>p.y>>p.z))throw std::runtime_error("invalid entity vector");for(int a=0;a<3;a++)if(!std::isfinite(p[a]))throw std::runtime_error("invalid entity vector");return p;}
inline Vec3 origin(const PointEntity& e){auto it=e.fields.find("origin");return it==e.fields.end()?Vec3{}:entityVector(it->second);}
inline std::string vectorText(Vec3 p){std::ostringstream o;o.imbue(std::locale::classic());o<<std::fixed<<std::setprecision(5)<<snap(p.x)<<' '<<snap(p.y)<<' '<<snap(p.z);return o.str();}
}
Geometry parseMap(const std::string& source){using namespace brushio;if(source.size()>16*1024*1024)throw std::runtime_error("MAP fragment exceeds 16 MiB");if(source.find("patchDef")!=source.npos||source.find("brushDef")!=source.npos)throw std::runtime_error("AutoLevel capture supports plane brushes, not patches or brush primitives.");Lexer l(source);Geometry g;for(auto t=l.next();!t.empty();t=l.next()){if(t!="{")throw std::runtime_error("expected MAP entity");PointEntity ent;bool brushes=false;while(true){t=l.next();if(t=="}")break;if(t.empty())throw std::runtime_error("unclosed MAP entity");if(t=="{"){Brush b;brushes=true;while(true){t=l.next();if(t=="}")break;l.put(t);Face f;for(auto& p:f.points)p=point(l);f.material=unquote(l.next());auto uv=l.next();if(uv=="["){f.u={l.num(),l.num(),l.num()};f.offsetU=l.num();l.expect("]");l.expect("[");f.v={l.num(),l.num(),l.num()};f.offsetV=l.num();l.expect("]");f.rotation=l.num();f.scaleU=l.num();f.scaleV=l.num();}else{l.put(uv);f.offsetU=l.num();f.offsetV=l.num();f.rotation=l.num();f.scaleU=l.num();f.scaleV=l.num();standardAxes(f);}if(std::abs(f.scaleU)<1e-9||std::abs(f.scaleV)<1e-9)throw std::runtime_error("invalid zero texture scale");t=l.next();while(t!="("&&t!="}"&&!t.empty()){f.attributes+=t+' ';t=l.next();}l.put(t);b.faces.push_back(f);if(b.faces.size()>64)throw std::runtime_error("brush exceeds 64 planes");}validateBrush(b);g.brushes.push_back(std::move(b));if(g.brushes.size()>16000)throw std::runtime_error("too many brushes");}else{auto valueToken=l.next();if(valueToken.empty()||valueToken=="}")throw std::runtime_error("missing entity field");auto k=unquote(t),v=unquote(valueToken);ent.fields[k]=v;}}auto it=ent.fields.find("classname");if(it!=ent.fields.end()&&it->second!="worldspawn"&&!brushes)g.entities.push_back(ent);}return g;}
bool contains(const Brush& b,Vec3 p,double epsilon){for(auto& f:b.faces)if(dot(f.normal(),p)>f.distance()+epsilon)return false;return true;}
Polyhedron polyhedron(const Brush& b){if(b.faces.size()<4||b.faces.size()>64)throw std::runtime_error("brush needs 4..64 planes");Polyhedron out;std::vector<Vec3> ns;std::vector<double> ds;bool axial=true;for(auto& f:b.faces){auto n=f.normal();ns.push_back(n);ds.push_back(f.distance());int axes=0;for(int a=0;a<3;a++)if(std::abs(n[a])>1e-7)axes++;axial&=axes==1;}
 if(axial){Vec3 lo{-1e30,-1e30,-1e30},hi{1e30,1e30,1e30};for(size_t f=0;f<ns.size();f++)for(int a=0;a<3;a++){if(ns[f][a]>.5)hi[a]=std::min(hi[a],ds[f]);if(ns[f][a]<-.5)lo[a]=std::max(lo[a],-ds[f]);}for(int a=0;a<3;a++)if(hi[a]-lo[a]<=1e-6||std::abs(hi[a])>1e20||std::abs(lo[a])>1e20)throw std::runtime_error("empty or unbounded brush");for(int i=0;i<8;i++)out.vertices.push_back({i&1?hi.x:lo.x,i&2?hi.y:lo.y,i&4?hi.z:lo.z});}
 else for(size_t a=0;a<ns.size();a++)for(size_t b=a+1;b<ns.size();b++)for(size_t c=b+1;c<ns.size();c++){double det=dot(ns[a],cross(ns[b],ns[c]));if(std::abs(det)<1e-9)continue;auto p=(cross(ns[b],ns[c])*ds[a]+cross(ns[c],ns[a])*ds[b]+cross(ns[a],ns[b])*ds[c])/det;bool in=true;for(size_t f=0;f<ns.size();f++)if(dot(ns[f],p)>ds[f]+.001){in=false;break;}if(in&&std::none_of(out.vertices.begin(),out.vertices.end(),[&](auto q){return near(p,q,.001);}))out.vertices.push_back(p);}
 if(out.vertices.size()<4)throw std::runtime_error("degenerate brush");out.min=out.max=out.vertices[0];for(auto p:out.vertices)for(int a=0;a<3;a++){out.min[a]=std::min(out.min[a],p[a]);out.max[a]=std::max(out.max[a],p[a]);}
 Vec3 center{};for(auto p:out.vertices)center=center+p;center=center/double(out.vertices.size());
 for(size_t f=0;f<ns.size();f++){std::vector<Vec3> face;Vec3 fc{};for(auto p:out.vertices)if(std::abs(dot(ns[f],p)-ds[f])<.002){face.push_back(p);fc=fc+p;}if(face.size()<3){out.polygons.push_back({});continue;}fc=fc/double(face.size());Vec3 u=unit(face[0]-fc),v=cross(ns[f],u);std::sort(face.begin(),face.end(),[&](auto a,auto b){return std::atan2(dot(a-fc,v),dot(a-fc,u))<std::atan2(dot(b-fc,v),dot(b-fc,u));});for(size_t i=1;i+1<face.size();i++)out.volume+=std::abs(dot(face[0]-center,cross(face[i]-center,face[i+1]-center)))/6;out.polygons.push_back(face);}
 if(!std::isfinite(out.volume)||out.volume<=1e-6)throw std::runtime_error("zero brush volume");return out;}
void validateBrush(const Brush& b){auto p=polyhedron(b);if(p.volume<=1)throw std::runtime_error("brush volume must exceed 1 cubic unit");for(auto v:p.vertices)for(int a=0;a<3;a++)if(!std::isfinite(v[a])||std::abs(v[a])>32000)throw std::runtime_error("brush coordinate outside +/-32000");}
Brush box(Vec3 lo,Vec3 hi,const std::string& material){Brush b;for(int d=0;d<6;d++){int axis=d%3==0?0:d%3==1?2:1;Vec3 n=vec(delta[d]),p=lo;p[axis]=d>=3?hi[axis]:lo[axis];Vec3 u=axis==0?Vec3{0,1,0}:Vec3{1,0,0},v=cross(n,u);Face f;f.points={p,p+v,p+u};f.material=material;brushio::standardAxes(f);b.faces.push_back(f);}return b;}
std::string writeBrush(const Brush& b){using namespace brushio;std::ostringstream o;o.imbue(std::locale::classic());o<<std::fixed<<std::setprecision(5)<<"{\n";for(auto& f:b.faces){for(auto p:f.points)point(o,p);o<<std::quoted(f.material)<<" [ "<<f.u.x<<' '<<f.u.y<<' '<<f.u.z<<' '<<f.offsetU<<" ] [ "<<f.v.x<<' '<<f.v.y<<' '<<f.v.z<<' '<<f.offsetV<<" ] "<<f.rotation<<' '<<f.scaleU<<' '<<f.scaleV;if(!f.attributes.empty())o<<' '<<f.attributes;o<<'\n';}o<<"}\n";return o.str();}
std::string writeEntity(const PointEntity& e){std::ostringstream o;o<<"{\n";for(auto& p:e.fields)o<<std::quoted(p.first)<<' '<<std::quoted(p.second)<<'\n';o<<"}\n";return o.str();}
std::string writeMap(const Geometry& g){std::string s="{\n\"classname\" \"worldspawn\"\n";for(auto& b:g.brushes)s+=writeBrush(b);s+="}\n";for(auto& e:g.entities)s+=writeEntity(e);return s;}
Geometry transformGeometry(const Geometry& g,Vec3 cell,const std::vector<BlockAction>& actions,Vec3 translation){Geometry out=g;Vec3 bias=transformPoint({},cell,actions)+translation;int det=1;for(auto a:actions)det*=determinant(a);for(auto& b:out.brushes)for(auto& f:b.faces){for(auto& p:f.points)p=transformPoint(p,cell,actions)+translation;if(det<0)std::swap(f.points[1],f.points[2]);for(int a=0;a<2;a++){auto& uv=a?f.v:f.u;auto& scale=a?f.scaleV:f.scaleU;auto& offset=a?f.offsetV:f.offsetU;auto cov=transformCovector(uv/scale,cell,actions);double n=length(cov);if(n<1e-12)throw std::runtime_error("invalid UV covector");uv=cov/n;scale=1/n;offset-=dot(cov,bias);}}
 for(auto& e:out.entities){e.fields["origin"]=brushio::vectorText(transformPoint(brushio::origin(e),cell,actions)+translation);auto angle=e.fields.find("angle");if(angle!=e.fields.end()){double yaw=std::stod(angle->second)*3.141592653589793/180;if(!std::isfinite(yaw))throw std::runtime_error("invalid entity angle");Vec3 dir{std::cos(yaw),std::sin(yaw),0};for(auto a:actions)dir=linear(dir,a);angle->second=std::to_string(std::atan2(dir.y,dir.x)*180/3.141592653589793);}auto angles=e.fields.find("angles");if(angles!=e.fields.end()){Vec3 a=brushio::entityVector(angles->second);double yaw=a.y*3.141592653589793/180;if(!std::isfinite(yaw))throw std::runtime_error("invalid entity angle");Vec3 dir{std::cos(yaw),std::sin(yaw),0};for(auto x:actions)dir=linear(dir,x);a.y=std::atan2(dir.y,dir.x)*180/3.141592653589793;angles->second=brushio::vectorText(a);}}
 return out;}
Geometry translateGeometry(const Geometry& g,Vec3 translation){return transformGeometry(g,{1,1,1},{},translation);}
Geometry rescaleGeometry(const Geometry& g,Vec3 factors){Geometry out=g;for(auto& b:out.brushes)for(auto& f:b.faces){for(auto& p:f.points)p=mul(p,factors);auto uv=[&](Vec3& axis,double& scale){auto c=div(axis/scale,factors);double n=length(c);axis=c/n;scale=1/n;};uv(f.u,f.scaleU);uv(f.v,f.scaleV);}for(auto& e:out.entities)e.fields["origin"]=brushio::vectorText(mul(brushio::origin(e),factors));return out;}
bool clipBrush(const Brush& b,Vec3 n,double d,Brush& result){auto p=polyhedron(b);bool in=false,out=false;for(auto v:p.vertices){in|=dot(n,v)<d-1e-6;out|=dot(n,v)>d+1e-6;}if(!in)return false;result=b;if(!out)return true;Face f;Vec3 u=unit(cross(n,std::abs(n.z)<.8?Vec3{0,0,1}:Vec3{0,1,0})),v=cross(n,u),a=n*d;f.points={a,a+v,a+u};f.material=b.faces[0].material;brushio::standardAxes(f);result.faces.push_back(f);try{auto clipped=polyhedron(result);std::vector<Face> used;for(size_t i=0;i<result.faces.size();i++)if(clipped.polygons[i].size()>=3)used.push_back(result.faces[i]);result.faces=std::move(used);return clipped.volume>1;}catch(...){return false;}}
Geometry clipGeometry(const Geometry& g,Vec3 lo,Vec3 hi){Geometry out;for(auto& b:g.brushes){Brush part=b;bool good=true;for(int a=0;a<3&&good;a++){Vec3 n{};n[a]=1;Brush next;good=clipBrush(part,n,hi[a],next);if(good)part=std::move(next);n[a]=-1;if(good){good=clipBrush(part,n,-lo[a],next);if(good)part=std::move(next);}}if(good)out.brushes.push_back(part);}for(auto e:g.entities){auto p=brushio::origin(e);bool in=true;for(int a=0;a<3;a++)in&=p[a]>=lo[a]&&p[a]<hi[a];if(in)out.entities.push_back(e);}return out;}
uint8_t generateFill(const Geometry& g,Vec3 cell){uint8_t f=0;auto center=cell*.5;for(int i=0;i<8;i++){auto c=mul({double(i&1),double((i>>1)&1),double((i>>2)&1)},cell);auto p=c+(center-c)*.1;for(auto& b:g.brushes)if(contains(b,p)){f|=1<<i;break;}}return f;}
}
